    raise AssertionError('Step 1: MediaFile class not defined')

# Check MediaFile inherits from ABC
for node in class_nodes:
    if node.name == 'MediaFile':
        # Check inheritance
        base_names = []
        for base in node.bases:
            if isinstance(base, ast.Name):
                base_names.append(base.id)

        if 'ABC' not in base_names:
            raise AssertionError('MediaFile should inherit from ABC')

        # Check for abstract method
        has_abstract = False
        for item in node.body:
            if isinstance(item, ast.FunctionDef) and item.name == 'display_info':
                # Check for abstractmethod decorator
                for decorator in item.decorator_list:
                    if isinstance(decorator, ast.Name) and decorator.id == 'abstractmethod':
                        has_abstract = True

        if not has_abstract:
            raise AssertionError('MediaFile missing abstract method display_info with @abstractmethod decorator')
